import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] input = readinti(scanner);
        int n = input[0];
        int m = input[1];
        System.out.println(app(n, m));
        scanner.close();
    }

    static int[] readinti(Scanner scanner) {
        String[] parts = scanner.nextLine().split(" ");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }

    static int egcd(int a, int b) {
        int r0 = a, r1 = b;
        int s0 = 1, s1 = 0;
        int t0 = 0, t1 = 1;
        while (r1 != 0) {
            int q = r0 / r1;
            int rTemp = r0; r0 = r1; r1 = rTemp - q * r1;
            int sTemp = s0; s0 = s1; s1 = sTemp - q * s1;
            int tTemp = t0; t0 = t1; t1 = tTemp - q * t1;
        }
        return r0;
    }

    static int[] tf(int n, int M) {
        int[] C = new int[n + 1];
        C[n] = 1;
        for (int k = n - 1; k >= 0; k--) {
            C[k] = (int)((long)C[k + 1] * (k + 1) % M);
            if (C[k] == 0) {
                break;
            }
        }
        return C;
    }

    static int app(int n, int M) {
        java.util.ArrayList<int[][]> K = new java.util.ArrayList<>();
        K.add(new int[][]{{1}});
        for (int i = 0; i < n - 1; i++) {
            int[][] Ki = K.get(i);
            int ni = Ki.length;
            int[][] Ki_ = new int[ni + i + 1][i + 2];
            for (int j = 0; j < ni; j++) {
                for (int k = 0; k < Ki[j].length; k++) {
                    for (int h = 0; h <= i; h++) {
                        Ki_[j + h][k] = (Ki_[j + h][k] + Ki[j][k]) % M;
                    }
                    Ki_[j + i + 1][i + 1] = (Ki_[j + i + 1][i + 1] + Ki[j][Ki[j].length - 1]) % M;
                }
            }
            K.add(Ki_);
        }
        int[] C = tf(n, M);
        int s = 0;
        for (int i = 1; i < n; i++) {
            int[][] Ki = K.get(i);
            int ni = Ki.length;
            int mi = Ki[0].length;
            int[][] Si = new int[ni][mi];
            for (int j = 0; j < ni; j++) {
                Si[j][mi - 1] = Ki[j][mi - 1];
                for (int k = mi - 2; k >= 0; k--) {
                    Si[j][k] = (Ki[j][k] + Si[j][k + 1]) % M;
                }
            }
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    Si[j][k] = (Si[j][k] + Si[j - 1][k]) % M;
                }
            }
            int si = 0;
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi - 1; k++) {
                    si += (int)((long)Ki[j][k] * Si[j - 1][k + 1] % M);
                    si %= M;
                }
            }
            int c = C[i + 1];
            si = (int)((long)si * c % M);
            s = (s + si) % M;
        }
        return s;
    }
}

